\section*{Convergence Theory Development}

\subsection*{Assumptions}
\begin{assumption}[Smoothness] \label{assump:smooth}
    The function $f$ is $L$-smooth: for all $x, y \in \R^d$,
    \[
        f(y) \le f(x) + \inner{\nabla f(x)}{y-x} + \frac{L}{2} \norm{y-x}^2.
    \]
\end{assumption}

\begin{assumption}[Stochastic Gradients] \label{assump:stochastic}
    At each iteration $t$, we observe $g_t = \nabla f(x_t) + \xi_t$, where $\xi_t$ is a random vector conditioned on $x_t$ satisfying
    \[
        \E[\xi_t \mid x_t] = 0, \quad \E[\norm{\xi_t}^2 \mid x_t] \le \sigma^2.
    \]
    The noise $\xi_t$ is independent across iterations given the history.
\end{assumption}

\begin{assumption}[Bounded Clipping Threshold] \label{assump:clipping}
    The clipping threshold $C > 0$ is a fixed constant. The clipped gradient $\tilde{g}_t = g_t / \max(1, \norm{g_t}/C)$ satisfies $\norm{\tilde{g}_t} \le C$ almost surely.
\end{assumption}

\begin{assumption}[Hyperparameters] \label{assump:hyper}
    $\beta_1, \beta_2 \in [0,1)$, $\eta > 0$, $\epsilon > 0$. We assume $\beta_1 < \sqrt{\beta_2}$ (standard condition for Adam-type convergence).
\end{assumption}

\begin{assumption}[Lower Bound] \label{assump:lower}
    $f$ is bounded below: $f^* = \inf_{x \in \R^d} f(x) > -\infty$.
\end{assumption}

% CORRECTED: Added bounded gradient assumption to enable rigorous bias bound
\begin{assumption}[Bounded Gradients] \label{assump:bounded_grad}
    The true gradient is uniformly bounded: there exists $G > 0$ such that $\norm{\nabla f(x)} \le G$ for all $x \in \R^d$.
\end{assumption}

\subsection*{Main Convergence Theorem}
\begin{theorem}[Convergence Rate for Clipped Adam] \label{thm:main}
    Under Assumptions \ref{assump:smooth}--\ref{assump:bounded_grad}, for any $T \ge 1$, the iterates of Clipped Adam satisfy
    \[
        \frac{1}{T} \sum_{t=1}^T \E\left[ \norm{\nabla f(x_t)}^2 \right]
        \le \frac{2(f(x_1)-f^*)}{\eta \alpha T} + \frac{B^2}{\epsilon \alpha} + \frac{L \eta K}{\alpha \sqrt{T}} + \mathcal{O}\left(\frac{\log T}{T}\right),
    \]
    where $\alpha = \frac{1}{C+\epsilon}$, 
    $B = \frac{2}{C}\left(\frac{2G^2+2\sigma^2}{C}\right)\frac{\beta_1}{(1-\beta_1)^2} + \frac{L \eta C}{\epsilon} \cdot \frac{\beta_1}{(1-\beta_1)^2} + \frac{2\sigma^2}{C(1-\beta_1)}$,
    and $K = \frac{2 C^2 d}{(1-\beta_1)^2 \epsilon}$.
    In particular, with a constant step size $\eta = \Theta(1/\sqrt{T})$, we obtain
    \[
        \frac{1}{T} \sum_{t=1}^T \E\left[ \norm{\nabla f(x_t)}^2 \right] = \mathcal{O}\left(\frac{1}{\sqrt{T}}\right) + \mathcal{O}(1).
    \]
    If a decreasing step size $\eta_t = \eta/\sqrt{t}$ is used, the constant bias term can be reduced to $\mathcal{O}(\log T/\sqrt{T})$, yielding an overall rate of $\mathcal{O}(\log T/\sqrt{T})$.
\end{theorem}

\subsection*{Theoretical Properties}
\begin{property}[Gradient Norm Bound]
    Clipping ensures $\norm{\tilde{g}_t} \le C$, which directly bounds the second moment estimates $v_t$ and the effective step size. This prevents the exploding gradient problem and stabilizes the adaptive learning rates.
\end{property}

\begin{property}[Bias-Variance Trade-off]
    Clipping introduces bias: $\E[\tilde{g}_t \mid x_t] \neq \nabla f(x_t)$ when $\norm{\nabla f(x_t)} > C$. The bias is bounded by $\norm{\E[\tilde{g}_t] - \nabla f(x_t)} \le \E[\norm{g_t} - C]_+$. Under bounded gradients (Assumption \ref{assump:bounded_grad}), this bias is uniformly bounded by a constant proportional to $C$.
\end{property}

\begin{property}[Comparison to Baselines]
    \begin{itemize}
        \item \textbf{SGD with clipping:} Achieves $\mathcal{O}(1/\sqrt{T})$ but without adaptive per-coordinate learning rates.
        \item \textbf{Adam (no clipping):} Requires bounded gradient assumption ($\norm{\nabla f} \le G$) for non-convex convergence; clipping removes this requirement for the update stability but the convergence analysis still needs bounded gradients to control the clipping bias.
        \item \textbf{Clipped Adam:} Combines adaptivity with robustness to heavy-tailed noise; the rate matches SGD in $T$ but with better constants in ill-conditioned problems.
    \end{itemize}
\end{property}

\subsection*{Discussion}
The convergence proof relies on controlling the bias introduced by clipping and momentum. The key lemma (Lemma \ref{lem:clip_bias}) shows that the inner product between the true gradient and the clipped gradient is at least the squared norm of the clipped gradient. This allows us to relate the progress in function value to the norm of the clipped gradient, and subsequently to the true gradient via the bias bound. The condition $\beta_1 < \sqrt{\beta_2}$ ensures that the effective step sizes do not grow too fast, a standard requirement in Adam convergence proofs. The $\mathcal{O}(\log T / T)$ term arises from the bias correction and the adaptive learning rate denominators; it can be eliminated with a slightly modified learning rate schedule (e.g., $\eta_t = \eta/\sqrt{t}$). The constant bias term $B^2/(\epsilon \alpha)$ reflects the fundamental limitation of clipped gradient methods with momentum: they converge to a neighborhood of a stationary point whose size depends on the clipping threshold and momentum. With decreasing step sizes, this neighborhood shrinks at rate $\mathcal{O}(\log T/\sqrt{T})$.

